def load_module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


identity = load_module('direct_runtime_identity', BENCHMARK / 'runtime_identity.py')
helper = load_module('direct_contract_runner', HERE / 'run_contracts.py')


def check(condition, message):
    if not condition:
        raise ValueError(message)


def read_json(path):
    return json.loads(Path(path).read_text())


def pinned(path, expected):
    path = Path(path).resolve(strict=True)
    check(expected and identity.sha(path) == expected, 'Changed pinned file: ' + str(path))
    return path


def file_record(path):
    path = Path(path).resolve(strict=True)
    return {'path': str(path), 'sha256': identity.sha(path)}


def hash_map(path):
    return {name: value['sha256'] for name, value in identity.tree_files(path).items()}


def base_runtime():
    pinned(BASE_DESCRIPTOR, BASE_SHA)
    descriptor = read_json(BASE_DESCRIPTOR)
    cp_path = pinned(descriptor['classpathFile'], descriptor['classpathFileSha256'])
    manifest_path = pinned(descriptor['classpathManifestFile'], descriptor['classpathManifestSha256'])
    cp = cp_path.read_text().strip()
    manifest = identity.classpath_manifest(cp)
    _, original = identity.original_identity()
    check(len(manifest) == 128 and manifest[1:] == original and manifest == read_json(manifest_path)
          and manifest[0]['files'] == 15 and manifest[0]['sha256'] == COMMON_PREFIX_SHA,
          'The fifteen common harness classes or original127 runtime changed')
    check(descriptor['productionEntryIndex'] == 2 and descriptor['diagnosticOnly'] is False,
          'Unexpected common runtime composition')
    production = identity.tree_files(manifest[2]['path'])
    check(len(production) == 2780 and sum(name.endswith('.class') for name in production) == 2778,
          'Unexpected frozen LMDB production tree')
    return {'descriptor': descriptor, 'classpath': cp, 'manifest': manifest, 'productionFiles': production}


def preserved_sources(generated):
    """Check the source bodies whose existing class files remain in the runtime."""
    source_map = read_json(identity.ORIGINAL_SOURCES)
    originals = {}
    for name in ('NativeResultMaterializer.java', 'NativeProjectedBindingSet.java'):
        path = MODULE / 'src/main/java' / PACKAGE / name
        pinned(path, source_map[path.relative_to(ROOT).as_posix()])
        originals[name] = path.read_text()
    materializer = (generated / PACKAGE / 'NativeResultMaterializer.java').read_text()
    bindings = (generated / PACKAGE / 'NativeProjectedBindingSet.java').read_text()

    def region(text, begin, end):
        check(text.count(begin) == text.count(end) == 1, 'Ambiguous retained source boundary')
        start = text.index(begin)
        return text[start:text.index(end, start)]

    plan_end = '/**\n * Evaluation-local last-value memo.'
    old = originals['NativeResultMaterializer.java']
    check(old.count(plan_end) == materializer.count(plan_end) == 1
          and old[:old.index(plan_end)] == materializer[:materializer.index(plan_end)],
          'Original Plan source, imports, or line positions changed')
    begin = '\t/** Last validated coordinates for each target, invalidated by accumulated source-slot changes. */'
    end = '\tprivate boolean allocate(NativeLmdbQuerySource currentSource) {'
    check(region(old, begin, end) == region(materializer, begin, end), 'FactorMemo or FactorPage source changed')
    old_bindings = originals['NativeProjectedBindingSet.java']
    begin = '\t/** Immutable row-independent projection metadata compiled once with its owning native row step. */'
    end = '\tstatic boolean enabled() {'
    check(region(old_bindings, begin, end) == region(bindings, begin, end), 'ProjectionLayout source changed')
    begin = '\t@Override\n\tpublic Iterator<Binding> iterator() {'
    end = '\t@Override\n\tpublic Set<String> getBindingNames() {'
    check(region(old_bindings, begin, end) == region(bindings, begin, end), 'Anonymous binding iterator changed')
    return {'planPrefixIdentical': True, 'factorNestedSourceIdentical': True,
            'projectionLayoutSourceIdentical': True, 'bindingIteratorSourceIdentical': True}


def reports(folder):
    totals = dict(classes=0, tests=0, failures=0, errors=0, skipped=0)
    cases, classpaths = [], set()
    paths = sorted((folder / 'surefire-reports').glob('TEST-*.xml'))
    for path in paths:
        suite = ET.parse(path).getroot()
        totals['classes'] += 1
        for key in ('tests', 'failures', 'errors', 'skipped'):
            totals[key] += int(suite.attrib.get(key, 0))
        properties = {p.attrib['name']: p.attrib.get('value', '') for p in suite.findall('./properties/property')}
        check(properties.get('surefire.test.class.path'), 'Missing actual Surefire execution classpath')
        classpaths.add(properties['surefire.test.class.path'])
        for case in suite.findall('testcase'):
            failure = case.find('failure')
            cases.append({'classname': case.attrib['classname'], 'name': case.attrib['name'].split('(', 1)[0],
                          'rawName': case.attrib['name'],
                          'failure': failure is not None, 'error': case.find('error') is not None,
                          'skipped': case.find('skipped') is not None,
                          'failureMessage': None if failure is None else failure.attrib.get('message', '')})
    check(len(classpaths) == 1 and len(cases) == totals['tests'], 'Incomplete or inconsistent Surefire reports')
    check(len({(c['classname'], c['rawName']) for c in cases}) == len(cases), 'Duplicate reported test case')
    return totals, cases, classpaths.pop(), paths


def require_red(receipt_path, seal_path=None):
    receipt_path = Path(receipt_path).resolve(strict=True)
    folder = receipt_path.parent
    seal_path = HERE / 'contract-seal.json' if seal_path is None else Path(seal_path)
    receipt, seal = read_json(receipt_path), read_json(seal_path)
    check(receipt.get('passedStage') is True and receipt.get('mode') == 'red'
          and receipt.get('moduleSourcesUnchanged') is True, 'Accepted feature-red evidence is required')
    pinned(folder / 'contract-seal.json', receipt['contractSealSha256'])
    check(read_json(folder / 'contract-seal.json') == seal, 'The accepted red seal changed')
    pinned(folder / (seal['className'] + '.java'), seal['testSourceSha256'])
    pinned(folder / 'NativeDirectValueMemo.java', seal['stubSourceSha256'])
    totals, cases, _, _ = reports(folder)
    expected = {'classes': 1, 'tests': len(seal['testMethods']), 'failures': len(seal['expectedRedFailures']),
                'errors': 0, 'skipped': 0}
    check(totals == receipt['results'] == expected
          and {c['name'] for c in cases} == set(seal['testMethods'])
          and {c['classname'] for c in cases} == {PACKAGE.replace('/', '.') + seal['className']}
          and {c['name'] for c in cases if c['failure']} == set(seal['expectedRedFailures'])
          and all(seal['failureMarker'] in c['failureMessage'] for c in cases if c['failure']),
          'Feature-red raw reports do not match their sealed intended failures')
    return receipt


def compile_stage(args):
    check(args.slot_granted, 'Compilation requires the exclusive Java slot')
    base = base_runtime()
    generated = args.generated.resolve(strict=True)
    origin = generated / 'source-receipt.json'
    generation = read_json(origin)
    check(generation.get('noProductionWrites') is True, 'Source generation did not preserve production sources')
    source_paths = {Path(path).resolve(strict=True): digest for path, digest in generation['sources'].items()}
    expected_paths = {generated / 'src' / PACKAGE / name for name in GENERATED_NAMES}
    check(set(source_paths) == expected_paths, 'Generator must pin exactly the three experimental Java sources')
    for path, digest in source_paths.items():
        pinned(path, digest)
    for key in ('sourcePatch', 'generator', 'redValidationReceipt', 'integrationRedValidationReceipt'):
        pinned(generation[key + 'File'], generation[key + 'Sha256'])
    pinned(generated / 'direct-memo-overlay.patch', generation['sourcePatchSha256'])
    require_red(generation['redValidationReceiptFile'])
    require_red(generation['integrationRedValidationReceiptFile'], HERE / 'integration-contract-seal.json')
    boundary = preserved_sources(generated / 'src')
    out = args.output.resolve()
    out.mkdir(parents=True, exist_ok=False)
    before = hash_map(MODULE / 'src')
    identity.write_new(out / 'sources-before.json', before)
    shutil.copytree(generated, out / 'generated')
    source_dir = out / 'generated/src' / PACKAGE
    for name in SUPPORT_NAMES:
        shutil.copyfile(BENCHMARK / 'src' / PACKAGE / name, source_dir / name)
    sources = [source_dir / name for name in sorted(GENERATED_NAMES | SUPPORT_NAMES)]
    source_receipt = {'format': 1, 'sources': {str(path): identity.sha(path) for path in sources},
                      'generationReceipt': file_record(out / 'generated/source-receipt.json'),
                      'originGenerationReceipt': file_record(origin),
                      'redValidationReceipt': file_record(generation['redValidationReceiptFile']),
                      'integrationRedValidationReceipt': file_record(generation['integrationRedValidationReceiptFile']),
                      'preservedSourceRegions': boundary, 'noProductionWrites': True}
    identity.write_new(out / 'generated/compiled-sources.json', source_receipt)
    tools = {name: file_record(path) for name, path in (
        ('builder', Path(__file__)), ('identityHelper', BENCHMARK / 'runtime_identity.py'),
        ('contractRunner', HERE / 'run_contracts.py'), ('javac', helper.JAVA_HOME / 'bin/javac'),
        ('generator', Path(generation['generatorFile'])))}
    inputs = {'sourceReceipt': file_record(out / 'generated/compiled-sources.json'),
              'generationReceipt': file_record(out / 'generated/source-receipt.json'),
              'sourcePatch': file_record(out / 'generated/direct-memo-overlay.patch'),
              'launcherSource': file_record(source_dir / 'DirectMemoLauncher.java'),
              'statisticsSource': file_record(source_dir / 'NativeDirectValueMemoStatistics.java'),
              'launcherOrigin': file_record(BENCHMARK / 'src' / PACKAGE / 'DirectMemoLauncher.java'),
              'statisticsOrigin': file_record(BENCHMARK / 'src' / PACKAGE / 'NativeDirectValueMemoStatistics.java')}
    emitted = out / 'emitted-classes'
    emitted.mkdir()
    command = [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g', '-proc:none', '-implicit:none',
               '-sourcepath', '', '-cp', base['classpath'], '-d', emitted, *sources]
    result = helper.run(out, 'compile', command)
    check(result['exit_code'] == 0, 'Compilation failed; see compile.log')
    emitted_files = identity.tree_files(emitted)
    check(set(emitted_files) == PREFIX | RETAINED, 'Unexpected emitted class files')
    check(emitted_files[PLAN] == base['productionFiles'][PLAN], 'Unchanged Plan bytes differ')
    prefix = out / 'classes'
    for name in sorted(PREFIX):
        target = prefix / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(emitted / name, target)
    prefix_files = identity.tree_files(prefix)
    cp = os.pathsep.join([str(prefix), base['classpath']])
    manifest = identity.classpath_manifest(cp)
    check(len(manifest) == 129 and manifest[1:] == base['manifest'], 'Common128 changed during compilation')
    for path, digest in source_receipt['sources'].items():
        pinned(path, digest)
    for record in [*inputs.values(), *tools.values()]:
        pinned(record['path'], record['sha256'])
    after = hash_map(MODULE / 'src')
    check(before == after, 'Production/test sources changed while compiling the overlay')
    identity.write_new(out / 'sources-after.json', after)
    (out / 'classpath.txt').write_text(cp + '\n')
    for name, value in (('classpath-manifest.json', manifest), ('emitted-class-files.json', emitted_files),
                        ('prefix-class-files.json', prefix_files),
                        ('original-production-class-files.json', base['productionFiles'])):
        identity.write_new(out / name, value)
    source_digest = identity.canonical_sha({Path(path).name: digest
                                           for path, digest in source_receipt['sources'].items()})
    receipt = {'format': 1, 'stage': 'compiled-awaiting-validation', 'compiledEpochNs': time.time_ns(),
               'memoVariant': 'identity-witness-v1', 'baseRuntimeDescriptor': file_record(BASE_DESCRIPTOR),
               'sourceIdentity': base['descriptor']['sourceIdentity'] + '+direct-memo-sources-sha256-' + source_digest,
               'inputs': inputs, 'tools': tools, 'preservedSourceRegions': boundary,
               'prefixTreeSha256': identity.tree_digest(prefix_files), 'timingPrefixClasses': sorted(PREFIX),
               'retainedClassFiles': {name: {'retained': base['productionFiles'][name],
                                           'emittedButNotSelected': emitted_files[name]} for name in sorted(RETAINED)},
               'productionSourceWritten': False, 'timingRuntimeDescriptorCreated': False}
    for key, filename in (('classpath', 'classpath.txt'), ('classpathManifest', 'classpath-manifest.json'),
                          ('emittedClassFiles', 'emitted-class-files.json'), ('prefixClassFiles', 'prefix-class-files.json'),
                          ('originalProductionClassFiles', 'original-production-class-files.json')):
        receipt[key] = file_record(out / filename)
    identity.write_new(out / 'compile-receipt.json', receipt)
    print(json.dumps({'compiledRuntime': str(out), 'contractOverlay': str(prefix), 'prefixClasses': 6,
                      'runtimeEntries': 129, 'descriptorCreated': False}))


def compiled_runtime(folder):
    folder = Path(folder).resolve(strict=True)
    receipt = read_json(folder / 'compile-receipt.json')
    check(receipt.get('stage') == 'compiled-awaiting-validation'
          and receipt.get('memoVariant') == 'identity-witness-v1', 'Missing strengthened compilation receipt')
    for record in [*receipt['inputs'].values(), *receipt['tools'].values()]:
        pinned(record['path'], record['sha256'])
    for record in receipt.values():
        if isinstance(record, dict) and set(record) == {'path', 'sha256'}:
            pinned(record['path'], record['sha256'])
    base = base_runtime()
    prefix = identity.tree_files(folder / 'classes')
    emitted = identity.tree_files(folder / 'emitted-classes')
    check(set(prefix) == PREFIX and prefix == read_json(folder / 'prefix-class-files.json')
          and identity.tree_digest(prefix) == receipt['prefixTreeSha256'], 'Timing prefix changed')
    check(emitted == read_json(folder / 'emitted-class-files.json')
          and all(prefix[name] == emitted[name] for name in PREFIX)
          and emitted[PLAN] == base['productionFiles'][PLAN], 'Compiler outputs changed')
    check(base['productionFiles'] == read_json(folder / 'original-production-class-files.json'),
          'Retained original production bytes changed')
    sources = read_json(receipt['inputs']['sourceReceipt']['path'])
    for path, digest in sources['sources'].items():
        pinned(path, digest)
    check(preserved_sources(folder / 'generated/src') == receipt['preservedSourceRegions'], 'Source boundary changed')
    cp = (folder / 'classpath.txt').read_text().strip()
    manifest = identity.classpath_manifest(cp)
    check(cp == os.pathsep.join([str(folder / 'classes'), base['classpath']])
          and manifest[1:] == base['manifest'] and manifest == read_json(folder / 'classpath-manifest.json'),
          'Compiled runtime composition changed')
    return {'folder': folder, 'receipt': receipt, 'base': base, 'classpath': cp, 'manifest': manifest,
            'prefixFiles': prefix, 'descriptor': {'sourceIdentity': receipt['sourceIdentity']}}


def run_existing(args):
    check(args.slot_granted, 'Existing tests require the exclusive Java slot')
    runtime = compiled_runtime(args.runtime)
    out = args.output.resolve()
    out.mkdir(parents=True, exist_ok=False)
    before = hash_map(MODULE / 'src')
    identity.write_new(out / 'sources-before.json', before)
    shutil.copyfile(__file__, out / 'runner-at-launch.py')
    classes, tests = out / 'classes', out / 'test-classes'
    shutil.copytree(runtime['base']['manifest'][2]['path'], classes)
    helper.copy_overlay(runtime['folder'] / 'classes', classes)
    fresh = (MODULE / 'target/test-classes').resolve(strict=True)
    fresh_files = identity.tree_files(fresh)
    check(fresh_files, 'Fresh module test support is missing')
    shutil.copytree(fresh, tests)
    check(identity.tree_files(tests) == fresh_files, 'Fresh test support changed while copying')
    identity.write_new(out / 'fresh-input-test-class-files.json', fresh_files)
    enabled = args.kind == 'enabled-lifetime'
    selected_classes = {ENABLED_LIFETIME_CLASS} if enabled else FOCUSED_CLASSES
    sources = [MODULE / 'src/test/java' / (name.replace('.', '/') + '.java') for name in sorted(selected_classes)]
    selection = (ENABLED_LIFETIME_CLASS.rsplit('.', 1)[1] + '#' + '+'.join(sorted(ENABLED_LIFETIME_METHODS))
                 if enabled else FOCUSED_SELECTION)
    expected_count = 8 if enabled else 106
    records = []
    for path in sources:
        archived = out / 'selected-test-sources' / path.name
        archived.parent.mkdir(exist_ok=True)
        shutil.copyfile(path, archived)
        records.append({'origin': file_record(path), 'archive': file_record(archived)})
    identity.write_new(out / 'selected-test-source-files.json', records)
    result = helper.run(out, 'compile-selected-tests', [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g',
        '-proc:none', '-implicit:none', '-sourcepath', '', '-cp', os.pathsep.join([str(classes), str(tests),
        runtime['base']['classpath']]), '-d', tests, *[record['archive']['path'] for record in records]])
    check(result['exit_code'] == 0, 'Selected test compilation failed')
    identity.write_new(out / 'production-class-files.json', hash_map(classes))
    identity.write_new(out / 'test-class-files.json', hash_map(tests))
    (out / 'target/tmp/fork-1').mkdir(parents=True)
    pom = helper.copied_pom(out, classes, tests)
    argv = [helper.MAVEN, '-o', '-Dmaven.repo.local=.m2_repo', '-Pquick', '-DskipTests=false', '-f', pom,
            '-Dtest=' + selection, '-DforkCount=1', '-Drdf4j.lmdb.test.maxHeap=4G',
            '-D' + DIRECT_PROPERTY + '=' + ('true' if enabled else 'false')]
    if enabled:
        argv.append('-D' + TRANSPORT_PROPERTY + '=off')
    argv += ['-Dsurefire.runOrder=alphabetical', 'surefire:test']
    executed = helper.run(out, 'tests', argv)
    (out / 'surefire-reports').mkdir()
    snippets = []
    for path in sorted((out / 'target/surefire-reports').glob('*')):
        if path.is_file():
            check(path.stat().st_mtime_ns >= executed['startedEpochNs'], 'Stale Surefire report')
            shutil.copyfile(path, out / 'surefire-reports' / path.name)
            if path.suffix == '.txt':
                snippets.extend(line for line in path.read_text().splitlines() if line.startswith('Tests run:'))
    totals, cases, execution_cp, xml_files = reports(out)
    execution_manifest = identity.classpath_manifest(execution_cp)
    check([entry['path'] for entry in execution_manifest[:2]] == [str(tests), str(classes)],
          'Surefire did not run isolated test/production copies first')
    identity.write_new(out / 'execution-classpath-manifest.json', execution_manifest)
    identity.write_new(out / 'test-cases.json', cases)
    identity.write_new(out / 'results.json', totals)
    after = hash_map(MODULE / 'src')
    identity.write_new(out / 'sources-after.json', after)
    evidence = 'Command: ' + ' '.join(map(str, argv)) + '\nReports: ' + str(out / 'surefire-reports') + '\n'
    evidence += '\n'.join(snippets) + '\n'
    (out / 'evidence.txt').write_text(evidence)
    print(evidence, flush=True)
    check(before == after and executed['exit_code'] == 0, 'Validation failed or module sources changed')
    check(totals == {'classes': len(sources), 'tests': expected_count, 'failures': 0, 'errors': 0, 'skipped': 0},
          'Missing, failing, or skipped validation cases')
    check({c['classname'] for c in cases} == selected_classes, 'Selected existing suite identities changed')
    if enabled:
        check({case['name'] for case in cases} == ENABLED_LIFETIME_METHODS,
              'Enabled lifetime selection differs from the exact eight existing methods')
        validate_enabled_properties(xml_files)
    receipt = {'format': 1, 'mode': 'green', 'kind': args.kind, 'passedStage': True,
               'directMemoEnabled': enabled, 'coordinateTransport': 'off' if enabled else 'unchanged default',
               'moduleSourcesUnchanged': True, 'results': totals, 'runtimeCompileReceipt': file_record(
                   runtime['folder'] / 'compile-receipt.json'), 'baseRuntimeDescriptor': file_record(BASE_DESCRIPTOR),
               'expectedTestMethods': sorted([c['classname'], c['rawName']] for c in cases),
               'testExecutionDependencies': 'workspace Maven dependencies after the mandatory root build',
               'frozenClasspathUsage': 'javac dependencies and copied LMDB production; fresh module test support',
               'selectedTestSourceFilesSha256': identity.sha(out / 'selected-test-source-files.json'),
               'freshInputTestClassFilesSha256': identity.sha(out / 'fresh-input-test-class-files.json')}
    for key, filename in (('resultsSha256', 'results.json'), ('productionClassFilesSha256', 'production-class-files.json'),
                          ('testClassFilesSha256', 'test-class-files.json'),
                          ('executionClasspathManifestSha256', 'execution-classpath-manifest.json')):
        receipt[key] = identity.sha(out / filename)
    identity.write_new(out / 'validation-receipt.json', receipt)


def validate_enabled_properties(xml_files):
    for path in xml_files:
        suite = ET.parse(path).getroot()
        properties = {item.attrib['name']: item.attrib.get('value', '')
                      for item in suite.findall('./properties/property')}
        check(properties.get(DIRECT_PROPERTY) == 'true' and properties.get(TRANSPORT_PROPERTY) == 'off',
              'Enabled lifetime XML does not record direct memo true and coordinate transport off')


def validate_tests(path, kind, runtime):
    folder = Path(path).resolve(strict=True)
    if folder.is_file():
        folder = folder.parent
    receipt = read_json(folder / 'validation-receipt.json')
    check(receipt.get('passedStage') is True and receipt.get('mode') == 'green'
          and receipt.get('moduleSourcesUnchanged') is True, 'Passing unchanged-source test evidence is required')
    for filename, key in (('results.json', 'resultsSha256'), ('production-class-files.json', 'productionClassFilesSha256'),
                          ('test-class-files.json', 'testClassFilesSha256'),
                          ('execution-classpath-manifest.json', 'executionClasspathManifestSha256')):
        pinned(folder / filename, receipt[key])
    totals, cases, execution_cp, report_paths = reports(folder)
    check(totals == receipt['results'] == read_json(folder / 'results.json')
          and all(totals[key] == 0 for key in ('failures', 'errors', 'skipped'))
          and all(not(c['failure'] or c['error'] or c['skipped']) for c in cases), 'Raw test reports are not green')
    if kind in ('contracts', 'integration'):
        seal_path = HERE / ('contract-seal.json' if kind == 'contracts' else 'integration-contract-seal.json')
        seal = read_json(seal_path)
        pinned(folder / 'contract-seal.json', receipt['contractSealSha256'])
        check(read_json(folder / 'contract-seal.json') == seal, 'Green seal differs')
        pinned(folder / (seal['className'] + '.java'), seal['testSourceSha256'])
        check(totals['classes'] == 1 and {c['name'] for c in cases} == set(seal['testMethods'])
              and {c['classname'] for c in cases} == {PACKAGE.replace('/', '.') + seal['className']},
              'Contract test selection differs')
        red = Path(receipt['redValidationDirectory']) / 'validation-receipt.json'
        require_red(red, seal_path)
        generation = read_json(runtime['receipt']['inputs']['generationReceipt']['path'])
        red_key = 'redValidationReceiptFile' if kind == 'contracts' else 'integrationRedValidationReceiptFile'
        check(red.resolve() == Path(generation[red_key]).resolve(),
              'Green tests do not follow the implementation generator\'s red stage')
        check(read_json(folder / 'execution-classpath-manifest.json')[2:]
              == read_json(red.parent / 'execution-classpath-manifest.json')[2:], 'Red/green dependencies changed')
    else:
        check(receipt['kind'] == kind and receipt['runtimeCompileReceipt'] == file_record(
            runtime['folder'] / 'compile-receipt.json'), 'Tests used another compiled overlay')
        if kind == 'focused':
            check(totals['tests'] == 106 and {c['classname'] for c in cases} == FOCUSED_CLASSES,
                  'Focused selection differs from the prescribed 106 cases')
        elif kind == 'enabled-lifetime':
            check(totals['classes'] == 1 and totals['tests'] == 8
                  and {case['classname'] for case in cases} == {ENABLED_LIFETIME_CLASS}
                  and {case['name'] for case in cases} == ENABLED_LIFETIME_METHODS,
                  'Enabled lifetime selection differs from the prescribed eight methods')
            check(receipt['directMemoEnabled'] is True and receipt['coordinateTransport'] == 'off',
                  'Enabled lifetime receipt has the wrong feature configuration')
            validate_enabled_properties(report_paths)
        pinned(folder / 'selected-test-source-files.json', receipt['selectedTestSourceFilesSha256'])
        for source in read_json(folder / 'selected-test-source-files.json'):
            pinned(source['archive']['path'], source['origin']['sha256'])
            pinned(source['origin']['path'], source['origin']['sha256'])
    expected = {**runtime['base']['productionFiles'], **runtime['prefixFiles']}
    physical = identity.tree_files(folder / 'classes')
    check(hash_map(folder / 'classes') == read_json(folder / 'production-class-files.json')
          and set(physical) == set(expected), 'Tested production class set changed')
    differences = {name for name in expected if physical[name] != expected[name]}
    check(differences <= {'maven-config.properties'}, 'Tests executed different implementation classes')
    test_files = identity.tree_files(folder / 'test-classes')
    check(hash_map(folder / 'test-classes') == read_json(folder / 'test-class-files.json')
          and not (set(test_files) & (PREFIX | RETAINED)), 'Test output shadows selected implementation classes')
    execution = identity.classpath_manifest(execution_cp)
    check(execution == read_json(folder / 'execution-classpath-manifest.json')
          and [entry['path'] for entry in execution[:2]] == [str(folder / 'test-classes'), str(folder / 'classes')],
          'Actual execution classpath changed')
    check(read_json(folder / 'tests-command.json')['exit_code'] == 0, 'Tests process was not successful')
    check(read_json(folder / 'sources-before.json') == read_json(folder / 'sources-after.json') == hash_map(MODULE / 'src'),
          'Validated module sources differ from current production/test sources')
    paths = [folder / 'validation-receipt.json', folder / 'results.json', folder / 'production-class-files.json',
             folder / 'test-class-files.json', folder / 'execution-classpath-manifest.json',
             folder / 'test-cases.json', folder / 'tests-command.json', *report_paths]
    return {'kind': kind, 'directory': str(folder), 'results': totals, 'files': [file_record(path) for path in paths],
            'executionDependencies': execution[2:], 'caseIdentities': sorted([c['classname'], c['rawName']] for c in cases),
            'allExecutedImplementationClassesMatchSelectedComposition': True,
            'allowedGeneratedResourceDifferences': sorted(differences)}


def validate_baseline(folder, runtime, focused):
    """Reconcile the already-run focused baseline without launching another test JVM."""
    folder = Path(folder).resolve(strict=True)
    if folder.is_file():
        folder = folder.parent
    receipt = read_json(folder / 'validation-receipt.json')
    check(receipt.get('mode') == 'baseline' and receipt.get('kind') == 'focused'
          and receipt.get('passedStage') is True and receipt.get('moduleSourcesUnchanged') is True,
          'The preserved passing focused baseline is required')
    totals, cases, cp, xml_files = reports(folder)
    check(totals == receipt['results'] == {'classes': 8, 'tests': 106, 'failures': 0, 'errors': 0, 'skipped': 0},
          'Preserved baseline did not run all 106 cases')
    case_ids = sorted([case['classname'], case['rawName']] for case in cases)
    check(case_ids == focused['caseIdentities'], 'Focused baseline and overlay cases differ')
    for filename, key in (('results.json', 'resultsSha256'), ('production-class-files.json', 'productionClassFilesSha256'),
                          ('test-class-files.json', 'testClassFilesSha256'),
                          ('execution-classpath-manifest.json', 'executionClasspathManifestSha256'),
                          ('selected-test-source-files.json', 'selectedTestSourceFilesSha256')):
        pinned(folder / filename, receipt[key])
    prior_descriptor = pinned(receipt['baseRuntimeDescriptor']['path'],
        'c46fe65a3515872535b55d0c979bf5f84e4d90b59168c86dd3bc14febaa244b2')
    prior = read_json(prior_descriptor)
    prior_cp = pinned(prior['classpathFile'], prior['classpathFileSha256']).read_text().strip()
    prior_manifest = identity.classpath_manifest(prior_cp)
    prior_manifest_file = pinned(prior['classpathManifestFile'], prior['classpathManifestFileSha256'])
    check(prior_manifest == read_json(prior_manifest_file)
          and prior_manifest[1:] == runtime['base']['manifest'], 'Baseline common128 bytes differ')
    expected = {**runtime['base']['productionFiles'], **identity.tree_files(prior_manifest[0]['path'])}
    actual = identity.tree_files(folder / 'classes')
    check(set(actual) == set(expected) and {name for name in actual if actual[name] != expected[name]}
          <= {'maven-config.properties'}, 'Baseline executed unexpected implementation bytes')
    check(hash_map(folder / 'classes') == read_json(folder / 'production-class-files.json')
          and hash_map(folder / 'test-classes') == read_json(folder / 'test-class-files.json'),
          'Preserved baseline class files changed')
    execution = identity.classpath_manifest(cp)
    check(execution == read_json(folder / 'execution-classpath-manifest.json')
          and execution[2:] == focused['executionDependencies'], 'Baseline and green dependencies differ')
    for source in read_json(folder / 'selected-test-source-files.json'):
        pinned(source['archive']['path'], source['origin']['sha256'])
        pinned(source['origin']['path'], source['origin']['sha256'])
    check(read_json(folder / 'sources-before.json') == read_json(folder / 'sources-after.json') == hash_map(MODULE / 'src'),
          'Preserved baseline sources differ from the current ownership sources')
    return {'directory': str(folder), 'results': totals, 'caseIdentities': case_ids,
            'baselineComposition': 'prior publication prefix over unchanged common128',
            'files': [file_record(path) for path in [folder / 'validation-receipt.json',
                folder / 'production-class-files.json', folder / 'test-class-files.json',
                folder / 'execution-classpath-manifest.json', folder / 'selected-test-source-files.json', *xml_files]],
            'sameSelectedCasesAndExecutionDependencies': True}


def freeze_stage(args):
    runtime = compiled_runtime(args.runtime)
    out = runtime['folder']
    check(not (out / 'runtime-descriptor.json').exists(), 'Runtime already frozen')
    validations = [validate_tests(args.contract_validation, 'contracts', runtime),
                   validate_tests(args.focused_validation, 'focused', runtime),
                   validate_tests(args.integration_validation, 'integration', runtime),
                   validate_tests(args.enabled_lifetime_validation, 'enabled-lifetime', runtime)]
    check(all(item['executionDependencies'] == validations[0]['executionDependencies'] for item in validations),
          'Contract, focused, integration, and enabled lifetime dependency bytes differ')
    baseline = validate_baseline(args.baseline_focused_validation, runtime, validations[1])
    sys.modules['runtime_identity'] = identity
    lifecycle_module = load_module('direct_lifecycle_validation', BENCHMARK / 'lifecycle-preflight.py')
    lifecycle_folder = args.lifecycle_validation.resolve(strict=True)
    if lifecycle_folder.is_file():
        lifecycle_folder = lifecycle_folder.parent
    lifecycle = lifecycle_module.qualify_lifecycle(out, lifecycle_folder, write_receipt=False)
    check(lifecycle == read_json(lifecycle_folder / 'validation-receipt.json'), 'Lifecycle receipt does not replay')
    validation_file = out / 'validation.json'
    identity.write_new(validation_file, {'format': 1, 'qualifiedForTiming': True, 'scope': SCOPE,
        'memoVariant': 'identity-witness-v1', 'records': validations, 'failures': 0, 'errors': 0, 'skipped': 0,
        'baselineFocused': baseline,
        'tests': sum(record['results']['tests'] for record in validations),
        'lifecycleReceipt': file_record(lifecycle_folder / 'validation-receipt.json'),
        'timingPrefixClassFiles': runtime['prefixFiles'], 'newPrefixClasses': 6,
        'preservedSourceRegions': runtime['receipt']['preservedSourceRegions'],
        'testDependencyScope': 'Matching recorded workspace Maven dependency bytes for red/green tests; common128 remains the separate immutable timing dependency set.',
        'memoryScope': 'Array reservations and slot limits do not bound payloads strongly retained by Values.',
        'primaryEstimand': 'Total query cost under normal garbage collection; resolver counts may differ.'})
    descriptor = {'format': 1, 'name': 'iteration-direct-memo-identity-witness', 'diagnosticOnly': False,
        'noProductionPromotion': True, 'memoVariant': 'identity-witness-v1',
        'sourceIdentity': runtime['receipt']['sourceIdentity'], 'classpathEntryCount': 129,
        'prefixEntryCount': 1, 'prefixClasses': sorted(PREFIX), 'productionEntryIndex': 3,
        'scope': SCOPE, 'allArmsShareCompiledRuntime': True, 'frozenEpochNs': time.time_ns()}
    inputs = runtime['receipt']['inputs']
    for key, path in (
        ('classpathFile', out / 'classpath.txt'), ('classpathManifestFile', out / 'classpath-manifest.json'),
        ('baseRuntimeDescriptorFile', BASE_DESCRIPTOR), ('sourceReceiptFile', inputs['sourceReceipt']['path']),
        ('overlayPatchFile', inputs['sourcePatch']['path']), ('launcherSourceFile', inputs['launcherSource']['path']),
        ('statisticsSourceFile', inputs['statisticsSource']['path']), ('validationFile', validation_file),
        ('lifecycleValidationFile', lifecycle_folder / 'validation-receipt.json'),
        ('compileReceiptFile', out / 'compile-receipt.json'), ('runtimeBuilderFile', Path(__file__))):
        path = Path(path)
        descriptor[key], descriptor[key + 'Sha256'] = str(path.resolve()), identity.sha(path)
    descriptor_path = out / 'runtime-descriptor.json'
    identity.write_new(descriptor_path, descriptor)
    trial = load_module('direct_comparison_validation', BENCHMARK / 'run-comparison.py')
    trial.validate_runtime(descriptor_path)
    print(json.dumps({'frozenRuntimeDescriptor': str(descriptor_path), 'sha256': identity.sha(descriptor_path),
                      'passingTests': sum(item['results']['tests'] for item in validations), 'primaryJvmsLaunched': 0}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    stages = parser.add_subparsers(dest='stage', required=True)
    compile_parser = stages.add_parser('compile')
    compile_parser.add_argument('--generated', type=Path, required=True)
    compile_parser.add_argument('--output', type=Path, default=PHASE / 'runtimes/identity-witness-v1')
    compile_parser.add_argument('--slot-granted', action='store_true')
    existing = stages.add_parser('run-existing')
    existing.add_argument('--runtime', type=Path, required=True)
    existing.add_argument('--kind', choices=('focused', 'enabled-lifetime'), default='focused')
    existing.add_argument('--output', type=Path, required=True)
    existing.add_argument('--slot-granted', action='store_true')
    freeze = stages.add_parser('freeze')
    freeze.add_argument('--runtime', type=Path, required=True)
    freeze.add_argument('--contract-validation', type=Path, required=True)
    freeze.add_argument('--focused-validation', type=Path, required=True)
    freeze.add_argument('--integration-validation', type=Path, required=True)
    freeze.add_argument('--enabled-lifetime-validation', type=Path, required=True)
    freeze.add_argument('--lifecycle-validation', type=Path, required=True)
    freeze.add_argument('--baseline-focused-validation', type=Path, default=ROOT /
        'result-coordinate-evidence/publication-qualified-followup/validation/baseline-focused-v2')
    args = parser.parse_args()
    {'compile': compile_stage, 'run-existing': run_existing, 'freeze': freeze_stage}[args.stage](args)


if __name__ == '__main__':
    main()
